pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 unlockTime1, uint128 unlockTime2) public {
        address sender = address(0x1234);
        vm.deal(sender, 2 ether);

        // Ensure unlockTime1 is in the future and unlockTime2 is less than unlockTime1
        vm.assume(unlockTime1 > block.timestamp);
        vm.assume(unlockTime2 > block.timestamp);
        vm.assume(unlockTime2 < unlockTime1);

        // First Put with a large future unlock time
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime1);
        uint storedUnlockTime1 = c.Acc(sender).unlockTime;

        // Second Put with a smaller (but still future) unlock time
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime2);
        uint storedUnlockTime2 = c.Acc(sender).unlockTime;

        // The stored unlock time must not decrease after the second Put.
        // Reference C keeps the larger of the two (since unlockTime1 > unlockTime2 > block.timestamp, it stays unlockTime1).
        // The mutant sets it to block.timestamp on the second call, which is smaller than unlockTime1, decreasing the stored value.
        assertTrue(storedUnlockTime2 >= storedUnlockTime1);
    }
}

