pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlock, uint256 amount, uint256 collectAmount) public {
        vm.assume(unlock > 0 && unlock <= type(uint64).max);
        vm.assume(amount >= 1 ether);
        vm.assume(collectAmount > 0 && collectAmount <= amount);
        address caller = address(0x1337);
        vm.deal(caller, amount);
        vm.startPrank(caller);
        c.Put{value: amount}(unlock);
        vm.warp(unlock);
        (uint256 balBefore, uint256 accBalBefore) = beforeValues(caller);
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        (uint256 balAfter, uint256 accBalAfter) = afterValues(caller);
        vm.stopPrank();
        if (block.timestamp == unlock) {
            assertTrue(reverted && balAfter == balBefore && accBalAfter == accBalBefore);
        }
    }

    function beforeValues(address caller) internal view returns (uint256 cBal, uint256 accBal) {
        cBal = address(c).balance;
        (, accBal) = c.Acc(caller);
    }

    function afterValues(address caller) internal view returns (uint256 cBal, uint256 accBal) {
        cBal = address(c).balance;
        (, accBal) = c.Acc(caller);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address user, uint am, uint unlockTime) public payable {
        require(am > 0);
        require(address(this).balance >= am);

        // Setup: fund and prepare account via Put
        c.Put{value: am}(unlockTime);

        // Record balance before Collect
