        c.Collect{value: 0}(am);
        reverted = false;

        // Record balance after Collect
        (, uint balanceAfter) = c.Acc(user);

        assert(!reverted ? balanceAfter == balanceBefore - am : true);
    }
    receive() external payable {}
}

